<?php
/** نمای فارسی مراحل ۷–۹؛ زمینه از کنترلر و مقادیر مالی از سرویس دریافت می‌شوند؛ خروجی escape می‌شود. */
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Db,Ctx,Request,Money,Jalali,Settings,Business};
use Agah\Erp\Modules\Trade\InvoiceService;
use Agah\Erp\Modules\Inventory\StockService;
if(!defined('ABSPATH')) exit;
$warehouse=Request::int('get','warehouse_id');$item=Request::int('get','item_id');$data=StockService::inventory($cid,Request::int('get','pg',1));$check=StockService::reconcile($cid);
?>
<section class="erp-card"><h2>موجودی لحظه‌ای</h2><?php TradeController::exportLink($cid,'inventory'); ?><p>ارزش انبار: <?php echo esc_html(Money::fmt($check['stock'],Ctx::unit())); ?><?php if($check['mode']==='inventory'): ?> | دفتر موجودی: <?php echo esc_html(Money::fmt($check['ledger'],Ctx::unit())); ?> | اختلاف: <strong class="<?php echo $check['difference']?'erp-err':'erp-ok'; ?>"><?php echo esc_html(Money::fmt($check['difference'],Ctx::unit())); ?></strong><?php else: ?> | روش ادواری؛ تطبیق حساب موجودی هنگام بستن دوره انجام می‌شود.<?php endif; ?></p>
<div class="erp-scroll"><table class="erp-table"><thead><tr><th>انبار</th><th>کالا</th><th>مقدار</th><th>ارزش</th><th>حداقل / هشدار</th><th>عملیات</th></tr></thead><tbody><?php foreach($data['rows'] as $r): ?><tr><td><?php echo esc_html($r['warehouse_name']); ?></td><td><?php echo esc_html($r['item_name']); ?></td><td><?php echo esc_html(Money::toFa(Money::qtyToDb((int)$r['qty']))); ?></td><td><?php echo esc_html(Money::fmt((int)$r['value'],Ctx::unit())); ?></td><td><?php echo esc_html(Money::toFa(Money::qtyToDb((int)$r['minimum']))); ?><?php if((int)$r['qty']<(int)$r['minimum']): ?><strong class="erp-err">کمبود موجودی</strong><?php endif; ?></td><td><a href="<?php echo esc_url(agah_erp_url(['c'=>$cid,'p'=>'inventory','warehouse_id'=>$r['warehouse_id'],'item_id'=>$r['item_id']])); ?>">کاردکس و حداقل</a></td></tr><?php endforeach; ?></tbody></table></div><?php self::pages($data['pages'],$data['page']); ?></section>
<?php if($warehouse&&$item):$k=StockService::kardex($cid,$warehouse,$item,Request::int('get','kp',1)); ?>
<section class="erp-card"><h3>کاردکس <?php echo esc_html(Business::row('items',$cid,$item)['name'].' / '.Business::row('warehouses',$cid,$warehouse)['name']); ?></h3><?php TradeController::exportLink($cid,'kardex'); ?><div class="erp-scroll"><table class="erp-table"><thead><tr><th>تاریخ</th><th>مبدأ</th><th>مقدار گردش</th><th>ارزش گردش</th><th>مانده مقدار</th><th>مانده ارزش</th></tr></thead><tbody><?php foreach($k['rows'] as $r): ?><tr><td><?php echo esc_html(Jalali::format($r['move_date'])); ?></td><td><?php echo esc_html(($r['source_type']==='invoice'?'فاکتور':'انبار').' #'.Money::toFa($r['source_id'])); ?></td><td><?php echo esc_html(Money::toFa(Money::qtyToDb((int)$r['qty_scaled']))); ?></td><td><?php echo esc_html(Money::fmt((int)$r['cost'],Ctx::unit())); ?></td><td><?php echo esc_html(Money::toFa(Money::qtyToDb($r['balance_qty']))); ?></td><td><?php echo esc_html(Money::fmt($r['balance_value'],Ctx::unit())); ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if($k['page']>1): ?><a href="<?php echo esc_url(add_query_arg('kp',$k['page']-1)); ?>">قبلی</a><?php endif; ?><?php if($k['page']<$k['pages']): ?><a href="<?php echo esc_url(add_query_arg('kp',$k['page']+1)); ?>">بعدی</a><?php endif; ?>
<?php if(Ctx::can('warehouse.edit')): ?><form method="post" class="erp-form"><?php self::form('module_stock_minimum',$cid,'inventory'); ?><input type="hidden" name="warehouse_id" value="<?php echo $warehouse; ?>"><input type="hidden" name="item_id" value="<?php echo $item; ?>"><?php self::input('qty','حداقل موجودی','','text','required inputmode="decimal"'); ?><button class="btn btn-outline" type="submit">ذخیره حداقل موجودی</button></form><?php endif; ?></section><?php endif; ?>
